  VALUES 
    (485::BIGINT, 'El mejor profe hasta ahora, explica súper bien, si es necesario repite las cosas, hace las clases muy divertidas y participativas, si estudia lo mínimo pasa el curso de lo más bien y con mucho cariño. No se hacen muchos quices, máximo 3 tareas pero si es necesario agrega más para ayudar con la nota.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2026-07-22T00:00:00+00:00'::TIMESTAMPTZ, '6e2ce0cfa3545ddfefba198f49ca653ca496be049fbda6c4d0b6b3430b5035a7'::TEXT, ARRAY[563]::BIGINT[]),
    (485::BIGINT, 'Las clases son muy cómicas. Explica la materia muy bien. En clase se practica bastante que ayuda mucho para aprender. Es muy flexible en temas de tareas y quizes. Da mucho material de apoyo y es muy simpático'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2026-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'e2a6c99a25c68b7136527d1c6b90a4ecde10ee8adbdb119f8b9ec325c1f3a47f'::TEXT, ARRAY[563]::BIGINT[]),
    (485::BIGINT, 'Es un excelente profe, se le entiende mucho y si tiene que explicar más o de diferente manera lo hace. Le da a los estudiantes mucho material para practicar y se preocupa de que en verdad entiendan. También es muy buena gente y sus clases son entretenidas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-01-11T00:00:00+00:00'::TIMESTAMPTZ, '6e146183fb844dfd6c265b9b68ebe8502f833a7397e352bf164ea453cd0bd9e0'::TEXT, ARRAY[563]::BIGINT[]),
