    (485::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2023-12-06T00:00:00+00:00'::TIMESTAMPTZ, '72b3d15ff02da8ca7a30d1a61e0da821893ab191231aaedcf62a6cb55c0221a3'::TEXT, ARRAY[563]::BIGINT[]),
    (485::BIGINT, 'Excelente Profe. No califica duro, ayuda demasiado. Lo que afecto un poco a la materia fue la falta de tiempo, pero de ahí en fuera todo bien.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases largas', 'Brinda apoyo']::TEXT[], '2023-11-27T00:00:00+00:00'::TIMESTAMPTZ, 'e47a52e74fb234d813f5fee06e54d53102a9b4af6e41f7ef5d17164414980651'::TEXT, ARRAY[563]::BIGINT[]),
