    (485::BIGINT, 'El profe realmente es excelente, me encantaban sus clases, la forma de enseñar y el carisma muy atento a las dudas'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-28T00:00:00+00:00'::TIMESTAMPTZ, '3c8a16a39e3746d2c0c0dc98def5ef02cf61c9505cf9dcc8b680cbbbb1866d78'::TEXT, ARRAY[605]::BIGINT[]),
    (485::BIGINT, 'Uno de los mejores profes de la escuela de matemática en temas de didáctica. Da muchos recursos y a pesar de deje bastantes trabajos vale la pena.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-17T00:00:00+00:00'::TIMESTAMPTZ, '9d5ed860c22e30da8de8ee1258ccce8da98c262a3a9f81018f713a86530f54d1'::TEXT, ARRAY[1690]::BIGINT[]),
    (485::BIGINT, 'DEMASIADO BUEN PROFE, brinda demasiada ayuda, da muchisimos ejemplos y prácticas.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes']::TEXT[], '2022-02-15T00:00:00+00:00'::TIMESTAMPTZ, '050a212325e0614f9c95308ae07c6c132a57c761cefebdbfec47340027d2b0b7'::TEXT, ARRAY[605]::BIGINT[]),
    (485::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2022-01-29T00:00:00+00:00'::TIMESTAMPTZ, 'ac680d997abd72a55e0f41e229bb4e34a2fc57692881bedea28ecf1718477c1a'::TEXT, ARRAY[605]::BIGINT[]),
    (485::BIGINT, 'Es un profesor espectacular. Es increíblemente organizado y está dispuesto a compartir su conocimiento de una manera muy empática y comprensiva. No duden en matricular con él!'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2022-01-15T00:00:00+00:00'::TIMESTAMPTZ, '2c0bfdffede4f7098d630b5ace58dc04a5a13f8174e8ab6a3847289442e2202d'::TEXT, ARRAY[605]::BIGINT[]),
    (485::BIGINT, 'Excelente profesor en este curso. Esperaba todas las semanas sus lecciones, porque lo que nos enseñab siempre era innovador y pertienente en nuestra formación. Encantado y motivado de ser su estudiante.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-01-06T00:00:00+00:00'::TIMESTAMPTZ, '427059219c9f21c3928e843ccce6a5c0883b4240eddb62d413d9103e8d38d190'::TEXT, ARRAY[1691]::BIGINT[]),
    (485::BIGINT, 'Es un excelente profesor, explica muy bien, es muy organizado y en virtual brinda a los estudiates el material que utiliza en las clases justo al acabar (son pdfs con ejercicios bien explicados y apuntes), cuesta que responda dudas por mensaje pero siempre esta dispuesto a ayudar y aclarar dudas.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-01-01T00:00:00+00:00'::TIMESTAMPTZ, 'f0a281ad85475a96959369e842e4e2c6d1cbfdbaa7425ef39176125fe6ef601e'::TEXT, ARRAY[605]::BIGINT[]),
    (485::BIGINT, 'Matricule todo lo que pueda con él. Es un profe excelente; explica super claro, deja evaluaciones sencillas y "nutritivas", tiene mucha disposición para atender dudas y es una teja de persona. Es SUPER organizado con la materia, las clases y las fechas. En general, 11/10'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-12-02T00:00:00+00:00'::TIMESTAMPTZ, '7495d690d4ec7490380195b52ef642d442b2f63bba87a4c5007c903c961e9b24'::TEXT, ARRAY[605]::BIGINT[]),
    (485::BIGINT, 'EXCELENTE PROFE. Nunca he conocido un profe de mate tan bueno como Carlos. Super amable y responde a todas las consultas de mate. Me encantaría que diera todos los cursos de mate de la carrera. Es super ordenado con el tecdigital y demasiadoooo buena gente.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-07-22T00:00:00+00:00'::TIMESTAMPTZ, '9f0417cf0d7b6c49cf14038c8efc4dc427611e901d8ef2c417ff4cb2d6bf4278'::TEXT, ARRAY[634]::BIGINT[]),
    (485::BIGINT, 'Un profesor con el que hubiera deseado llevar todos mis cursos de matemáticas, es lo máximo. Poder matricular con él es un éxito.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-07-01T00:00:00+00:00'::TIMESTAMPTZ, '16b896ec9d5440b6c0967646504e1d74b6d3c2b9cd821f64d883e02facfdec29'::TEXT, ARRAY[634]::BIGINT[]),
    (485::BIGINT, 'Sus clases son excelentes, explica bastante bien toda la materia, se preocupa bastante de que se entienda todo lo que explica y da una excelente preparación para los quices y examenes.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-26T00:00:00+00:00'::TIMESTAMPTZ, '02e5bd005b11ce6bece97fccf6be16367ca926d843ed6c9c3cf394ce7666e8dc'::TEXT, ARRAY[634]::BIGINT[]),
    (485::BIGINT, 'Excelente profe, de los mejores cursos de didáctica que he recibido. Se aprende mucho.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-05-14T00:00:00+00:00'::TIMESTAMPTZ, '8b48dd10cd75c2930e0f47a9a21ce3699f7ade11158c4ca517975f147325dbca'::TEXT, ARRAY[1689]::BIGINT[]),
    (485::BIGINT, 'Es uno de los mejores profesores que he tenido de verdad que se nota la vocación que tiene por la forma como da la clases y explica. Si tiene la posibilidad de matricular con él no lo dude en cualquier materia.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-02-19T00:00:00+00:00'::TIMESTAMPTZ, 'c0ac6c924369e4a7a661d729eb4d7581762b7c4f967110691f07a410240266dd'::TEXT, ARRAY[563]::BIGINT[]),
    (485::BIGINT, 'Uno de los mejores profes de la escuela de mate, hace que la clase sea súper ligera y entretenida, resuelve ejercicios de exámenes anteriores en clases y contesta súper rápido las dudas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-01-26T00:00:00+00:00'::TIMESTAMPTZ, 'd885e8977aa655dd3e32a3069d6ecaee93ed659fa6db4f57718344071f958baa'::TEXT, ARRAY[634]::BIGINT[]),
    (485::BIGINT, 'Excelente profe y persona. Explicaciones claras y concisas. Fomenta la práctica de la materia a través de porcentajes extra. Utiliza metodologías de enseñanza novedosas.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Da crédito extra', 'Aspectos de calificación claros']::TEXT[], '2021-01-15T00:00:00+00:00'::TIMESTAMPTZ, 'f13153106b0026def00f4291dc2da940ced431a4ba85297331c0bcda6f6abafc'::TEXT, ARRAY[563]::BIGINT[]),
