    (485::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, 'af0fce6b85893986729637bce41d535726cd63288810a14c82afc1f644200e44'::TEXT, ARRAY[923]::BIGINT[]),
    (485::BIGINT, 'Excelente profesor, demuestra calidad en sus lecciones e interés por sus estudiantes. Se nota que le encanta enseñar'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-20T00:00:00+00:00'::TIMESTAMPTZ, '7cade5111fd9da604c6a32e925c5bd13aebcfd4912135facaa31006be2002df3'::TEXT, ARRAY[1672]::BIGINT[]),
    (485::BIGINT, 'Es indudablemente uno de los mejores profesores que he tenido en cursos de matemática. En el primer semestre virtual se adaptó muy bien a la nueva modalidad y siempre nos brindó toda la materia y práctica para que pudiéramos estudiar. En hora consulta es muy atento a responder todas las dudas!'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-17T00:00:00+00:00'::TIMESTAMPTZ, 'fa17adc195e0dc957fbe955a0e21be5901846df972049b53cbe1cba9328db7f9'::TEXT, ARRAY[634]::BIGINT[]),
